	@Test
	void parsedMinusWithDisjointChildrenRejectsAnUnrelatedIncomingBinding() throws Exception {
		String query = "SELECT * WHERE { "
				+ "{ ?left <urn:minus-left> <urn:left> } "
				+ "MINUS { ?right <urn:minus-right> <urn:right> } "
				+ "?unrelated <urn:unrelated> <urn:value> . }";
		ParsedTupleQuery unoptimizedQuery = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
		List<Statement> statements = List.of(
				VF.createStatement(VF.createIRI("urn:left-subject"), VF.createIRI("urn:minus-left"),
						VF.createIRI("urn:left")),
				VF.createStatement(VF.createIRI("urn:right-subject"), VF.createIRI("urn:minus-right"),
						VF.createIRI("urn:right")),
				VF.createStatement(VF.createIRI("urn:unrelated-subject"), VF.createIRI("urn:unrelated"),
						VF.createIRI("urn:value")));
		List<BindingSet> expected = evaluate(unoptimizedQuery.getTupleExpr(), new ListTripleSource(statements));

		ParsedTupleQuery optimizedQuery = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
		QueryRoot optimized = new QueryRoot(optimizedQuery.getTupleExpr());
		new QueryJoinOptimizer(new DisjointMinusCostStatistics(), new ListTripleSource(statements))
				.optimize(optimized, null, EmptyBindingSet.getInstance());
		assertThat(statementPredicates(optimized))
				.as("the fixture must feed an unrelated sibling binding into MINUS")
				.startsWith("urn:unrelated");

		List<BindingSet> actual = evaluate(optimized, new ListTripleSource(statements));
		assertThat(expected).hasSize(1);
		assertThat(actual)
				.as("MINUS children with disjoint variables must ignore an unrelated outer binding")
				.containsExactlyInAnyOrderElementsOf(expected);
	}

